// Brighter than the generated scene, so the rain reads through the app's frosted glass.
export const SCENE = RAW
  .replace('<stop offset="0" stop-color="#0a5f2a" stop-opacity="0"/>', '<stop offset="0" stop-color="#0f7a36" stop-opacity="0.15"/>')
  .replace('<stop offset="0.6" stop-color="#139a45" stop-opacity="0.55"/>', '<stop offset="0.5" stop-color="#1fc35a" stop-opacity="0.8"/>')
  .replace(
    '<stop offset="0.55" stop-color="#000000" stop-opacity="0"/><stop offset="1" stop-color="#000000" stop-opacity="0.75"/>',
    '<stop offset="0.7" stop-color="#000000" stop-opacity="0"/><stop offset="1" stop-color="#000000" stop-opacity="0.3"/>',
  )
  .replace(/(<text class="c" y="\d+" font-size="\d+" opacity=")([\d.]+)"/g, (_, head: string, value: string) =>
    `${head}${Math.min(0.95, Number(value) * 1.6 + 0.1).toFixed(2)}"`)
